}
function loadGame() {
  try {
    const raw = localStorage.getItem("signal_save");
    if (!raw) return false;
    const s = JSON.parse(raw);
    SignalGameLogic.normalizeSavedGame(s);
    G = s.G;
    cardUid = s.cardUid || 0;
    viewedPlayer = s.viewedPlayer || 0;
    pendingNames = s.pendingNames || [];
    pendingPortraits = s.pendingPortraits || [];
    return true;
  } catch (e) {
    return false;
  }
}
function clearSave() {
  localStorage.removeItem("signal_save");
}

function remoteStateIngressOptions(game) {
  const tileDefinitions = buildTerrainDeck(false);
