    (player) => player?.isSynth === true,
  );
  return {
    strict: true,
    equipmentCards: EQ_CARDS,
    eventCards: buildEventDeck(2, hasSynth, false),
    tileDefinitions,
    crashTiles: CRASH_HEXES_DEFAULT.map((tile) => ({
      ...tile,
      type: "crash_site",
      revealed: true,
    })),
    allowedTileImages: [
      ...new Set([
        ...Object.values(TILE_IMAGE_MAP),
        ...tileDefinitions.map((tile) => tile.imgOverride).filter(Boolean),
      ]),
    ],
  };
}

