function hexPtsB(cx, cy, sz) {
  sz = sz || SZB - 2;
  let s = "";
  for (let i = 0; i < 6; i++) {
    const a = (Math.PI / 3) * i - Math.PI / 6;
    s += `${(cx + sz * Math.cos(a)).toFixed(1)},${(cy + sz * Math.sin(a)).toFixed(1)} `;
  }
  return s.trim();
}

